class MyDataset(Dataset):
    def __init__(self, X, y):
        self.X = X
        self.y = y

    def __len__(self):
        return len(self.X)

    def __getitem__(self, idx):
        x = self.X[idx]
        y = self.y[idx]

        # Convert HWC numpy image -> CHW torch tensor
        if isinstance(x, np.ndarray):
            x = torch.from_numpy(x).float()
        else:
            x = torch.tensor(x, dtype=torch.float32)

        if x.ndim == 3 and x.shape[-1] == 3:
            x = x.permute(2, 0, 1)

        # Normalize to [0, 1]
        if x.max() > 1:
            x = x / 255.0

        # y currently contains image arrays; convert to class label
        # 1 -> watermark, 0 -> no_watermark based on source split setup
        if isinstance(y, np.ndarray):
            label = torch.tensor(1 if idx < len(self.X) else 0, dtype=torch.long)
        else:
            label = torch.tensor(int(y), dtype=torch.long)

        return x, label

