class MyDataset(Dataset):
    def __init__(self, X, y):
        # Convert numpy arrays to torch tensors with correct dtypes/shapes
        # X expected as (N, H, W, C) -> convert to (N, C, H, W)
        self.X = torch.from_numpy(X).float().permute(0, 3, 1, 2)
        # y currently contains image arrays; build binary class labels instead
        # Since train_test_split was done as (watermarked, nonwatermarked),
        # infer labels from whether sample exactly matches non-watermarked target.
        y_labels = np.array([1 if np.array_equal(X[i], y[i]) else 0 for i in range(len(X))], dtype=np.int64)
        self.y = torch.from_numpy(y_labels).long()

    def __len__(self):
        return len(self.X)

    def __getitem__(self, idx):
        return self.X[idx], self.y[idx]
